//! Raw FFI bindings to link-grammar's public C API, generated by bindgen
//! from `link-includes.h`. The `link-grammar` crate wraps them in a safe
//! API.

#![expect(
    non_camel_case_types,
    non_upper_case_globals,
    reason = "bindgen keeps the C names"
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
